ST.xhtml:p:
RTrigge(CLK := g_bO2CalExecute);
IF RTrigge.Q THEN
  For i := 0 TO 10 BY 1 DO 
    g_StOxygenCal[i].Ao := 0.0;
    g_StOxygenCal[i].Pressure := 0.0;  
    g_StOxygenCal[i].Done := FALSE;  (*初始化空气气压标定数组*)
  END_FOR;
  CalNum := -1;
  GasCalDeltMax := 0.0;
  g_bO2CalDone := FALSE;
  O2CalState := 10;
END_IF;

CASE O2CalState OF
  0:
    O2CalState := 0;
  10:(*初始化气体*)
    g_boMasterValve := FALSE;
    g_uoSharePressureOut := 0;
    g_uoMasterPressureOut := 0;
    g_boAirValve:= FALSE;
    g_boOxygenValve := FALSE;
    g_boNirtogenValve := FALSE;
    g_uoAirPressureOut := 0;
    g_uoNirtogenPressureOut := 0;
    g_uoOxygenPressureOut := 0;   
    O2CalState := 20; 
  20:(*按采集点顺序输出标定电压*)
    GasCalTon1(IN:= FALSE);
    GasCalTon2(IN:= FALSE);
    GasCalTon3(IN:= FALSE);
    CalNum := CalNum +1;
    IF CalNum = 0 THEN
      DAOutputVol := 0.2;
      O2CalState := 50;
    ELSIF CalNum = 1 THEN
      DAOutputVol := 0.4;
      O2CalState := 50;
    ELSIF CalNum = 2 THEN
      DAOutputVol := 0.7;
      O2CalState := 50;
    ELSIF CalNum = 3 THEN
      DAOutputVol := 1.0;
      O2CalState := 50;
    ELSIF CalNum = 4 THEN
      DAOutputVol := 2.1;
      O2CalState := 50;
    ELSIF CalNum = 5 THEN
      DAOutputVol := 5.0;
      O2CalState := 50;
    ELSIF CalNum = 6 THEN
      DAOutputVol := 10.0;
      O2CalState := 50;
    ELSE
      O2CalState := 100;
    END_IF;    
  50:(*输出电压出气*)
    DAOutputVolAna := LREAL_TO_UINT((32767.0 / 10.0) * DAOutputVol);   
    bDAOutputVolEnable :=TRUE;

    GasCalTon1(IN:= TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_nGasCalDelayTime)));
    IF GasCalTon1.Q THEN
      GasCalTon1(IN:= FALSE);
      O2CalState := 60;
    END_IF;
  60:(*采集气压*)   
    GasCalTon2(IN:= TRUE,PT := T#3000ms); (*超时跳过*)
    GasCalTon3(IN:= (g_CutPreVariance < CutPreVarianceSet AND g_CutPreAverage > 0.0),PT := T#1000ms); (*气压方差稳定*)
    IF GasCalTon3.Q OR GasCalTon2.Q THEN
      g_StOxygenCal[CalNum].Ao := DAOutputVol;
      g_StOxygenCal[CalNum].Pressure := g_CutPreAverage;  (*电压-气压存到标定数组*)
      g_StOxygenCal[CalNum].Done := TRUE;
      GasCalTon2(IN:= FALSE);
      GasCalTon3(IN:= FALSE);
      O2CalState := 20;
    END_IF;
  100:(*找最大气压,气压标定数据差值最大的区段*)   
    STGasCalDelt[1] := g_StOxygenCal[1].Pressure - g_StOxygenCal[0].Pressure;
    STGasCalDelt[2] := g_StOxygenCal[2].Pressure - g_StOxygenCal[1].Pressure;
    STGasCalDelt[3] := g_StOxygenCal[3].Pressure - g_StOxygenCal[2].Pressure;
    STGasCalDelt[4] := g_StOxygenCal[4].Pressure - g_StOxygenCal[3].Pressure;
    STGasCalDelt[5] := g_StOxygenCal[5].Pressure - g_StOxygenCal[4].Pressure;
    STGasCalDelt[6] := g_StOxygenCal[6].Pressure - g_StOxygenCal[5].Pressure; 
    For i := 1 to 6 BY 1 DO 
      IF STGasCalDelt[i] > GasCalDeltMax THEN
        GasCalDeltMax := STGasCalDelt[i];
        GasCalDeltMaxi := i;
      END_IF;
    END_FOR; 
    O2CalState := 110; 
  110:(*补采点判断*)
    IF g_StOxygenCal[GasCalDeltMaxi].Ao > 2.1 THEN  (*补2个点*)
      DAVolRepair1 := g_StOxygenCal[GasCalDeltMaxi-1].Ao + (g_StOxygenCal[GasCalDeltMaxi].Ao - g_StOxygenCal[GasCalDeltMaxi-1].Ao)/3.0;
      DAVolRepair2 := g_StOxygenCal[GasCalDeltMaxi-1].Ao + 2.0*(g_StOxygenCal[GasCalDeltMaxi].Ao - g_StOxygenCal[GasCalDeltMaxi-1].Ao)/3.0;
    ELSE     (*补1个点*)
      DAVolRepair1 := g_StOxygenCal[GasCalDeltMaxi-1].Ao + (g_StOxygenCal[GasCalDeltMaxi].Ao - g_StOxygenCal[GasCalDeltMaxi-1].Ao)/2.0;
    END_IF;
    O2CalState := 120;
  120:(*补采点1*)
    DAOutputVolAna := LREAL_TO_UINT((32767.0 / 10.0) * DAVolRepair1);   
    bDAOutputVolEnable :=TRUE;

    GasCalTon1(IN:= TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_nGasCalDelayTime)));
    IF GasCalTon1.Q THEN
      GasCalTon1(IN:= FALSE);
      O2CalState := 130;
    END_IF;
  130:(*采集气压*)    
    GasCalTon2(IN:= TRUE,PT := T#3000ms); (*超时跳过*)
    GasCalTon3(IN:= (g_CutPreVariance < CutPreVarianceSet AND g_CutPreAverage >= 0.0),PT := T#1000ms); (*气压方差稳定*)
    IF GasCalTon3.Q OR GasCalTon2.Q THEN
      g_StOxygenCal[7].Ao := DAVolRepair1;
      g_StOxygenCal[7].Pressure := g_CutPreAverage;  (*电压-气压存到标定数组*)
      g_StOxygenCal[7].Done := TRUE;
      GasCalTon2(IN:= FALSE);
      GasCalTon3(IN:= FALSE);
      O2CalState := 140;
    END_IF; 
  140:(*是否补采点2*)   
    IF g_StOxygenCal[GasCalDeltMaxi].Ao > 2.4 THEN
      O2CalState := 150;
    ELSE
      O2CalState := 200;
    END_IF;
  150:(*补采点2*)
    DAOutputVolAna := LREAL_TO_UINT((32767.0 / 10.0) * DAVolRepair2);   
    bDAOutputVolEnable :=TRUE;

    GasCalTon1(IN:= TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_nGasCalDelayTime)));
    IF GasCalTon1.Q THEN
      GasCalTon1(IN:= FALSE);
      O2CalState := 160;
    END_IF;
  160:(*采集气压*) 
    GasCalTon2(IN:= TRUE,PT := T#3000ms); (*超时跳过*)  
    GasCalTon3(IN:= (g_CutPreVariance < CutPreVarianceSet AND g_CutPreAverage > 0.0),PT := T#1000ms); (*气压方差稳定*)
    IF GasCalTon3.Q OR GasCalTon2.Q THEN
      g_StOxygenCal[8].Ao := DAVolRepair2;
      g_StOxygenCal[8].Pressure := g_CutPreAverage;  (*电压-气压存到标定数组*)
      g_StOxygenCal[8].Done := TRUE;
      GasCalTon2(IN:= FALSE);
      GasCalTon3(IN:= FALSE);
      O2CalState := 200;
    END_IF; 

  200:(*关气,气压标定完成*)
      (*气压标定结果数组冒泡排序,排除0组*)
    FOR i := 0 TO 8 BY 1 DO
      FOR j := 0 TO (8-i) BY 1 DO
        IF g_StOxygenCal[j].Ao > g_StOxygenCal[j+1].Ao AND g_StOxygenCal[j].Ao<>0.0 AND g_StOxygenCal[j+1].Ao<>0.0 THEN
          temp := g_StOxygenCal[j];
          g_StOxygenCal[j] := g_StOxygenCal[j+1];
          g_StOxygenCal[j+1] := temp;     
        END_IF;
      END_FOR;
    END_FOR;
    bDAOutputVolEnable := FALSE;
    g_bO2CalExecute := FALSE;
    g_bO2CalDone := TRUE;
    O2CalState := 0;
END_CASE;

(*氧气电压输出*)
IF bDAOutputVolEnable THEN
    g_boMasterValve := TRUE;
    g_uoSharePressureOut := DAOutputVolAna;
    g_uoMasterPressureOut := DAOutputVolAna;
    g_boOxygenValve:= TRUE;  
    g_uoOxygenPressureOut := DAOutputVolAna; 
END_IF;
FTrigge1(CLK := bDAOutputVolEnable);
IF FTrigge1.Q THEN
  g_boMasterValve := FALSE;
  g_uoSharePressureOut := 0;
  g_uoMasterPressureOut := 0;
  g_boOxygenValve:= FALSE;
  g_uoOxygenPressureOut := 0; 
END_IF;

IF g_bPlcResetBuffer OR g_bGasCalStop THEN
  bDAOutputVolEnable:=FALSE;
  g_bO2CalExecute := FALSE;
  O2CalState := 0;
  g_bGasCalStop := FALSE;
END_IF;
